import type {
  NormalizedOutputOptions,
  Plugin,
  PluginContext,
  RenderedChunk,
  SourceMap,
} from "rollup";
import { header } from "../../src/header";

describe("Header plugin", () => {
  const testRenderChunk = async (
    headerValue: string,
    code: string,
  ): Promise<{ code: string; map: SourceMap }> => {
    const plugin: Plugin = header(headerValue);
    if (typeof plugin.renderChunk !== "function") {
      throw new Error("Plugin does not have a renderChunk hook");
    }
    const result = await plugin.renderChunk.call(
      {} as PluginContext,
      code,
      {} as RenderedChunk,
      {} as NormalizedOutputOptions,
      { chunks: {} },
    );
    if (!result) {
      throw new Error("Plugin rendered no chunk");
    }

    return result as { code: string; map: SourceMap };
  };

  test("should prepend header to code", async () => {
    const headerValue = "/* Copyright 2024 */\n";
    const code = 'console.log("Hello, world!");';
    const result = await testRenderChunk(headerValue, code);
    expect(result.code).toBe(
      '/* Copyright 2024 */\nconsole.log("Hello, world!");',
    );
    expect(result.map).toBeDefined();
  });

  test("should prepend multiline header", async () => {
    const headerValue = "/*\n * Copyright 2024\n * All rights reserved\n */\n";
    const code = "const x = 42;";
    const result = await testRenderChunk(headerValue, code);
    expect(result.code).toBe(
      "/*\n * Copyright 2024\n * All rights reserved\n */\nconst x = 42;",
    );
  });

  test("should work with empty code", async () => {
    const headerValue = "// Header\n";
    const code = "";
    const result = await testRenderChunk(headerValue, code);
    expect(result.code).toBe("// Header\n");
  });

  test("should work with empty header", async () => {
    const headerValue = "";
    const code = 'console.log("test");';
    const result = await testRenderChunk(headerValue, code);
    expect(result.code).toBe('console.log("test");');
  });
});
